package com.smart.ecommerce.service;
import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.javamail.*;import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class SmtpEmailService implements EmailService{ private final JavaMailSender mailSender; @Value("${spring.mail.from:no-reply@example.com}") private String from; public void sendEmailVerificationOtp(String email,String name,String otp){send(email,"Verify your email","<h2>Email verification</h2><p>Hello "+name+", use this code to verify your account.</p><h1>"+otp+"</h1>");} public void sendPasswordResetOtp(String email,String name,String otp){send(email,"Reset your password","<h2>Password reset</h2><p>Hello "+name+", use this code to reset your password.</p><h1>"+otp+"</h1>");} private void send(String to,String subject,String html){ try{ var m=mailSender.createMimeMessage(); var h=new MimeMessageHelper(m,true,"UTF-8");h.setFrom(from);h.setTo(to);h.setSubject(subject);h.setText(html,true);mailSender.send(m);}catch(Exception ignored){}} }
